-- Sequence and defined type
CREATE SEQUENCE IF NOT EXISTS migrations_id_seq;
CREATE SEQUENCE IF NOT EXISTS jobs_id_seq;
CREATE SEQUENCE IF NOT EXISTS users_id_seq;
CREATE SEQUENCE IF NOT EXISTS failed_jobs_id_seq;
CREATE SEQUENCE IF NOT EXISTS permissions_id_seq;
CREATE SEQUENCE IF NOT EXISTS roles_id_seq;
CREATE SEQUENCE IF NOT EXISTS newspapers_id_seq;
CREATE SEQUENCE IF NOT EXISTS shops_id_seq;
CREATE SEQUENCE IF NOT EXISTS invoices_id_seq;
CREATE SEQUENCE IF NOT EXISTS invoice_items_id_seq;

DROP TABLE IF EXISTS "public"."migrations";
-- Table Definition
CREATE TABLE "public"."migrations" (
    "id" int4 NOT NULL DEFAULT nextval('migrations_id_seq'::regclass),
    "migration" varchar(255) NOT NULL,
    "batch" int4 NOT NULL,
    PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "public"."password_reset_tokens";
-- Table Definition
CREATE TABLE "public"."password_reset_tokens" (
    "email" varchar(255) NOT NULL,
    "token" varchar(255) NOT NULL,
    "created_at" timestamp(0),
    PRIMARY KEY ("email")
);

DROP TABLE IF EXISTS "public"."sessions";
-- Table Definition
CREATE TABLE "public"."sessions" (
    "id" varchar(255) NOT NULL,
    "user_id" int8,
    "ip_address" varchar(45),
    "user_agent" text,
    "payload" text NOT NULL,
    "last_activity" int4 NOT NULL,
    PRIMARY KEY ("id")
);


-- Indices
CREATE INDEX sessions_user_id_index ON public.sessions USING btree (user_id);
CREATE INDEX sessions_last_activity_index ON public.sessions USING btree (last_activity);

DROP TABLE IF EXISTS "public"."cache";
-- Table Definition
CREATE TABLE "public"."cache" (
    "key" varchar(255) NOT NULL,
    "value" text NOT NULL,
    "expiration" int8 NOT NULL,
    PRIMARY KEY ("key")
);


-- Indices
CREATE INDEX cache_expiration_index ON public.cache USING btree (expiration);

DROP TABLE IF EXISTS "public"."cache_locks";
-- Table Definition
CREATE TABLE "public"."cache_locks" (
    "key" varchar(255) NOT NULL,
    "owner" varchar(255) NOT NULL,
    "expiration" int8 NOT NULL,
    PRIMARY KEY ("key")
);


-- Indices
CREATE INDEX cache_locks_expiration_index ON public.cache_locks USING btree (expiration);

DROP TABLE IF EXISTS "public"."jobs";
-- Table Definition
CREATE TABLE "public"."jobs" (
    "id" int8 NOT NULL DEFAULT nextval('jobs_id_seq'::regclass),
    "queue" varchar(255) NOT NULL,
    "payload" text NOT NULL,
    "attempts" int2 NOT NULL,
    "reserved_at" int4,
    "available_at" int4 NOT NULL,
    "created_at" int4 NOT NULL,
    PRIMARY KEY ("id")
);


-- Indices
CREATE INDEX jobs_queue_index ON public.jobs USING btree (queue);

DROP TABLE IF EXISTS "public"."job_batches";
-- Table Definition
CREATE TABLE "public"."job_batches" (
    "id" varchar(255) NOT NULL,
    "name" varchar(255) NOT NULL,
    "total_jobs" int4 NOT NULL,
    "pending_jobs" int4 NOT NULL,
    "failed_jobs" int4 NOT NULL,
    "failed_job_ids" text NOT NULL,
    "options" text,
    "cancelled_at" int4,
    "created_at" int4 NOT NULL,
    "finished_at" int4,
    PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "public"."users";
-- Table Definition
CREATE TABLE "public"."users" (
    "id" int8 NOT NULL DEFAULT nextval('users_id_seq'::regclass),
    "name" varchar(255) NOT NULL,
    "email" varchar(255) NOT NULL,
    "email_verified_at" timestamp(0),
    "password" varchar(255) NOT NULL,
    "remember_token" varchar(100),
    "created_at" timestamp(0),
    "updated_at" timestamp(0),
    PRIMARY KEY ("id")
);


-- Indices
CREATE UNIQUE INDEX users_email_unique ON public.users USING btree (email);

DROP TABLE IF EXISTS "public"."failed_jobs";
-- Table Definition
CREATE TABLE "public"."failed_jobs" (
    "id" int8 NOT NULL DEFAULT nextval('failed_jobs_id_seq'::regclass),
    "uuid" varchar(255) NOT NULL,
    "connection" text NOT NULL,
    "queue" text NOT NULL,
    "payload" text NOT NULL,
    "exception" text NOT NULL,
    "failed_at" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);


-- Indices
CREATE UNIQUE INDEX failed_jobs_uuid_unique ON public.failed_jobs USING btree (uuid);

DROP TABLE IF EXISTS "public"."permissions";
-- Table Definition
CREATE TABLE "public"."permissions" (
    "id" int8 NOT NULL DEFAULT nextval('permissions_id_seq'::regclass),
    "name" varchar(255) NOT NULL,
    "guard_name" varchar(255) NOT NULL,
    "created_at" timestamp(0),
    "updated_at" timestamp(0),
    PRIMARY KEY ("id")
);


-- Indices
CREATE UNIQUE INDEX permissions_name_guard_name_unique ON public.permissions USING btree (name, guard_name);

DROP TABLE IF EXISTS "public"."model_has_permissions";
-- Table Definition
CREATE TABLE "public"."model_has_permissions" (
    "permission_id" int8 NOT NULL,
    "model_type" varchar(255) NOT NULL,
    "model_id" int8 NOT NULL,
    CONSTRAINT "model_has_permissions_permission_id_foreign" FOREIGN KEY ("permission_id") REFERENCES "public"."permissions"("id") ON DELETE CASCADE,
    PRIMARY KEY ("permission_id","model_id","model_type")
);


-- Indices
CREATE INDEX model_has_permissions_model_id_model_type_index ON public.model_has_permissions USING btree (model_id, model_type);

DROP TABLE IF EXISTS "public"."roles";
-- Table Definition
CREATE TABLE "public"."roles" (
    "id" int8 NOT NULL DEFAULT nextval('roles_id_seq'::regclass),
    "name" varchar(255) NOT NULL,
    "guard_name" varchar(255) NOT NULL,
    "created_at" timestamp(0),
    "updated_at" timestamp(0),
    PRIMARY KEY ("id")
);


-- Indices
CREATE UNIQUE INDEX roles_name_guard_name_unique ON public.roles USING btree (name, guard_name);

DROP TABLE IF EXISTS "public"."model_has_roles";
-- Table Definition
CREATE TABLE "public"."model_has_roles" (
    "role_id" int8 NOT NULL,
    "model_type" varchar(255) NOT NULL,
    "model_id" int8 NOT NULL,
    CONSTRAINT "model_has_roles_role_id_foreign" FOREIGN KEY ("role_id") REFERENCES "public"."roles"("id") ON DELETE CASCADE,
    PRIMARY KEY ("role_id","model_id","model_type")
);


-- Indices
CREATE INDEX model_has_roles_model_id_model_type_index ON public.model_has_roles USING btree (model_id, model_type);

DROP TABLE IF EXISTS "public"."role_has_permissions";
-- Table Definition
CREATE TABLE "public"."role_has_permissions" (
    "permission_id" int8 NOT NULL,
    "role_id" int8 NOT NULL,
    CONSTRAINT "role_has_permissions_permission_id_foreign" FOREIGN KEY ("permission_id") REFERENCES "public"."permissions"("id") ON DELETE CASCADE,
    CONSTRAINT "role_has_permissions_role_id_foreign" FOREIGN KEY ("role_id") REFERENCES "public"."roles"("id") ON DELETE CASCADE,
    PRIMARY KEY ("permission_id","role_id")
);

DROP TABLE IF EXISTS "public"."newspapers";
-- Table Definition
CREATE TABLE "public"."newspapers" (
    "id" int8 NOT NULL DEFAULT nextval('newspapers_id_seq'::regclass),
    "name" varchar(255) NOT NULL,
    "publisher_name" varchar(255),
    "language" varchar(255),
    "frequency" varchar(255) NOT NULL DEFAULT 'daily'::character varying,
    "status" varchar(255) NOT NULL DEFAULT 'active'::character varying,
    "created_at" timestamp(0),
    "updated_at" timestamp(0),
    "deleted_at" timestamp(0),
    "price" numeric(10,2),
    "cost_price" numeric(10,2),
    PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "public"."shops";
-- Table Definition
CREATE TABLE "public"."shops" (
    "id" int8 NOT NULL DEFAULT nextval('shops_id_seq'::regclass),
    "name" varchar(255) NOT NULL,
    "owner_name" varchar(255),
    "phone" varchar(255),
    "email" varchar(255),
    "whatsapp_phone" varchar(255),
    "preferred_invoice_delivery" varchar(255),
    "address" text,
    "credit_limit" numeric(12,2) NOT NULL DEFAULT '0'::numeric,
    "opening_balance" numeric(12,2) NOT NULL DEFAULT '0'::numeric,
    "status" varchar(255) NOT NULL DEFAULT 'active'::character varying,
    "created_at" timestamp(0),
    "updated_at" timestamp(0),
    "deleted_at" timestamp(0),
    PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "public"."invoices";
-- Table Definition
CREATE TABLE "public"."invoices" (
    "id" int8 NOT NULL DEFAULT nextval('invoices_id_seq'::regclass),
    "invoice_date" date NOT NULL,
    "shop_id" int8 NOT NULL,
    "created_by" int8 NOT NULL,
    "total_amount" numeric(12,2) NOT NULL DEFAULT '0'::numeric,
    "status" varchar(255) NOT NULL DEFAULT 'draft'::character varying,
    "created_at" timestamp(0),
    "updated_at" timestamp(0),
    "deleted_at" timestamp(0),
    "notes" text,
    CONSTRAINT "invoices_created_by_foreign" FOREIGN KEY ("created_by") REFERENCES "public"."users"("id"),
    CONSTRAINT "invoices_shop_id_foreign" FOREIGN KEY ("shop_id") REFERENCES "public"."shops"("id") ON DELETE CASCADE,
    PRIMARY KEY ("id")
);


-- Indices
CREATE INDEX invoices_invoice_date_index ON public.invoices USING btree (invoice_date);
CREATE INDEX invoices_status_index ON public.invoices USING btree (status);
CREATE INDEX invoices_deleted_at_index ON public.invoices USING btree (deleted_at);
CREATE INDEX invoices_invoice_date_deleted_at_index ON public.invoices USING btree (invoice_date, deleted_at);

DROP TABLE IF EXISTS "public"."invoice_items";
-- Table Definition
CREATE TABLE "public"."invoice_items" (
    "id" int8 NOT NULL DEFAULT nextval('invoice_items_id_seq'::regclass),
    "invoice_id" int8 NOT NULL,
    "newspaper_id" int8 NOT NULL,
    "quantity" int4 NOT NULL,
    "unit_price" numeric(10,2) NOT NULL,
    "total_price" numeric(12,2) NOT NULL,
    "created_at" timestamp(0),
    "updated_at" timestamp(0),
    "deleted_at" timestamp(0),
    CONSTRAINT "invoice_items_invoice_id_foreign" FOREIGN KEY ("invoice_id") REFERENCES "public"."invoices"("id") ON DELETE CASCADE,
    CONSTRAINT "invoice_items_newspaper_id_foreign" FOREIGN KEY ("newspaper_id") REFERENCES "public"."newspapers"("id") ON DELETE CASCADE,
    PRIMARY KEY ("id")
);


-- Indices
CREATE INDEX invoice_items_deleted_at_index ON public.invoice_items USING btree (deleted_at);








